questionvariables.text:
/* 45-degree mirror line  y = x + c  (never an axis) */
c : rand([-1, 0, 1]);
lineexpr : x + c;

/* L-shape size and placement */
length : rand([3, 4]);
height : rand([3, 4]);
gap : rand([1, 2]);
bx : rand([2, 3]);
by : bx + c - height - gap;   /* guarantees the whole shape sits strictly below the line */
start_x : bx;
start_y : by;

/* Base L-shape (teacher shape) */
base_shape : [
  [start_x, start_y],
  [start_x + length, start_y],
  [start_x + length - 1, start_y + 1],
  [start_x + 1, start_y + 1],
  [start_x + 1, start_y + height],
  [start_x, start_y + height]
];

/* Reflection across y = x + c :  (x,y) -> (y - c, x + c) */
reflected_shape : map(lambda([p], [p[2] - c, p[1] + c]), base_shape);

/* Student's draggable starting shape: a copy on the FAR side of the line
   (upper-left), clear of the red original and not the answer. */
student_shape : map(lambda([p], [p[1] - 7, p[2] + 4]), base_shape);

/* Targets used only by the question tests */
t_trans : map(lambda([p], [p[1] + 2, p[2] + 1]), base_shape);   /* a translation of the original */
t_yaxis : map(lambda([p], [-p[1], p[2]]), base_shape);          /* reflection in the y-axis */
t_xaxis : map(lambda([p], [p[1], -p[2]]), base_shape);          /* reflection in the x-axis */
wrong_shift : map(lambda([p], [p[1] + 1, p[2]]), reflected_shape);

feedbackvariables.text:
student_shape : sort([sP1, sP2, sP3, sP4, sP5, sP6]);
cent(P) := block([m : length(P), ax, ay], ax : apply("+", map(first, P))/m, ay : apply("+", map(second, P))/m, sort(map(lambda([q], [q[1] - ax, q[2] - ay]), P)));
stu_c : cent([sP1, sP2, sP3, sP4, sP5, sP6]);
base_c : cent(base_shape);
refl_yaxis : sort(map(lambda([p], [-p[1], p[2]]), base_shape));
refl_xaxis : sort(map(lambda([p], [p[1], -p[2]]), base_shape));
refl_yx : sort(map(lambda([p], [p[2], p[1]]), base_shape));
